// Scores and ranks Apollo results by seniority and demand gen relevance.
// Returns top N contacts per account.

const apolloResponse = $json;
const company = $('Code in JavaScript').first()?.json || {};
const config = { contactsPerAccount: 10 };

const people = Array.isArray(apolloResponse.people) ? apolloResponse.people : [];

if (people.length === 0) {
  return {
    json: {
      ...company,
      contactCount: 0,
      topContactIds: [],
      rankedContacts: []
    }
  };
}

function scoreContact(person) {
  let score = 0;
  const title = (person.title || '').toLowerCase();
  const seniority = (person.seniority || '').toLowerCase();

  // Seniority tier
  if (seniority === 'c_suite' || title.includes('cmo') || title.includes('chief marketing officer')) {
    score += 40;
  } else if (seniority === 'vp' || title.includes('vp ') || title.includes('vice president')) {
    score += 30;
  } else if (seniority === 'director' || title.includes('director')) {
    score += 20;
  } else {
    score += 10;
  }

  // Demand gen / ABM bonus
  if (
    title.includes('demand gen') ||
    title.includes('abm') ||
    title.includes('account based') ||
    title.includes('demand generation')
  ) {
    score += 15;
  }

  return score;
}

const ranked = people
  .map(p => ({
    id: p.id,
    firstName: p.first_name,
    lastName: p.last_name,
    title: p.title,
    email: p.email,
    seniority: p.seniority,
    linkedinUrl: p.linkedin_url,
    _score: scoreContact(p)
  }))
  .sort((a, b) => b._score - a._score);

const topContacts = ranked.slice(0, config.contactsPerAccount);

return {
  json: {
    ...company,
    contactCount: people.length,
    topContactIds: topContacts.map(c => c.id),
    rankedContacts: topContacts
  }
};
